package server

import (
	"crypto/sha256"
	"database/sql"
	"encoding/base64"
	"encoding/json"
	"errors"
	"math"
	"sort"
	"strconv"
	"strings"
)

// Room auth rules (v10/v11) and PDUs: hashes, signatures, event IDs.
// The rules mirror Synapse's event_auth.py, quirks included; pdu_test.go
// checks them against cases generated by Synapse.

type stateTuple struct{ typ, key string }

// authState holds the state an event is checked against, by (type, state_key).
type authState map[stateTuple]*Event

var (
	createTuple = stateTuple{"m.room.create", ""}
	plTuple     = stateTuple{"m.room.power_levels", ""}
	jrTuple     = stateTuple{"m.room.join_rules", ""}
)

// roomRules lists what differs between the supported room versions.
type roomRules struct {
	implicitCreator bool // v11: the creator is the create event's sender
	newRedaction    bool // v11 redaction algorithm
}

func rulesFor(version string) (roomRules, bool) {
	switch version {
	case "10":
		return roomRules{}, true
	case "11":
		return roomRules{implicitCreator: true, newRedaction: true}, true
	}
	return roomRules{}, false
}

// knownRoomVersions are the versions a create event may name (any server's).
var knownRoomVersions = map[string]bool{"1": true, "2": true, "3": true, "4": true, "5": true,
	"6": true, "7": true, "8": true, "9": true, "10": true, "11": true, "12": true}

// maxPDUSize is the spec's limit on a whole PDU in canonical JSON.
const maxPDUSize = 65536

// ---- reading content the way the auth rules do ----

// contentOf decodes event content keeping numbers exact. Not an object → nil.
func contentOf(e *Event) map[string]any {
	if e == nil {
		return nil
	}
	v, err := decodeJSONNumbers(e.Content)
	if err != nil {
		return nil
	}
	m, _ := v.(map[string]any)
	return m
}

func membershipOf(e *Event) string {
	s, _ := contentOf(e)["membership"].(string)
	return s
}

func domainOf(id string) string {
	_, d, _ := strings.Cut(id, ":")
	return d
}

// isUserID matches Synapse's UserID.from_string: "@", then something with a colon.
func isUserID(s string) bool {
	return strings.HasPrefix(s, "@") && strings.Contains(s[1:], ":")
}

// asLevel is roughly Python's int(). v10+ only allows integers anyway.
func asLevel(v any) int64 {
	switch x := v.(type) {
	case json.Number:
		if n, err := x.Int64(); err == nil {
			return n
		}
		if f, err := x.Float64(); err == nil && !math.IsInf(f, 0) && !math.IsNaN(f) && math.Abs(f) < 1<<62 {
			return int64(f)
		}
	case bool:
		if x {
			return 1
		}
	case string:
		if n, err := strconv.ParseInt(strings.TrimSpace(x), 10, 64); err == nil {
			return n
		}
	}
	return 0
}

// isInt is Python's `type(v) is int` for decoded JSON: a plain integer literal.
func isInt(v any) bool {
	n, ok := v.(json.Number)
	if !ok {
		return false
	}
	_, err := strconv.ParseInt(string(n), 10, 64)
	return err == nil
}

func creatorOf(r roomRules, create *Event) string {
	if r.implicitCreator {
		return create.Sender
	}
	s, _ := contentOf(create)["creator"].(string)
	return s
}

func userPowerLevel(r roomRules, uid string, auth authState) int64 {
	if pl := auth[plTuple]; pl != nil {
		c := contentOf(pl)
		users, _ := c["users"].(map[string]any)
		if v, ok := users[uid]; ok && v != nil {
			return asLevel(v)
		}
		if v, ok := c["users_default"]; ok && v != nil {
			return asLevel(v)
		}
		return 0
	}
	if create := auth[createTuple]; create != nil && creatorOf(r, create) == uid {
		return 100
	}
	return 0
}

func namedLevel(auth authState, name string, def int64) int64 {
	pl := auth[plTuple]
	if pl == nil {
		return def
	}
	if v, ok := contentOf(pl)[name]; ok && v != nil {
		return asLevel(v)
	}
	return def
}

func sendLevel(typ string, isState bool, auth authState) int64 {
	c := contentOf(auth[plTuple])
	events, _ := c["events"].(map[string]any)
	if v, ok := events[typ]; ok && v != nil {
		return asLevel(v)
	}
	key, def := "events_default", int64(0)
	if isState {
		key, def = "state_default", 50
	}
	if v, ok := c[key]; ok && v != nil {
		return asLevel(v)
	}
	return def
}

func canFederate(auth authState) bool {
	create := auth[createTuple]
	if create == nil {
		return false
	}
	v, ok := contentOf(create)["m.federate"]
	return !ok || v == true
}

// ---- auth event selection ----

// authTypes is the auth events selection (Synapse: auth_types_for_event).
func authTypes(ev *Event) []stateTuple {
	if ev.Type == "m.room.create" {
		return nil
	}
	out := []stateTuple{createTuple, plTuple, {"m.room.member", ev.Sender}}
	add := func(t stateTuple) {
		for _, have := range out {
			if have == t {
				return
			}
		}
		out = append(out, t)
	}
	if ev.Type == "m.room.member" && ev.StateKey != nil {
		c := contentOf(ev)
		m, _ := c["membership"].(string)
		if m == "join" || m == "invite" || m == "knock" {
			add(jrTuple)
		}
		add(stateTuple{"m.room.member", *ev.StateKey})
		if m == "invite" {
			if tpi, ok := c["third_party_invite"].(map[string]any); ok {
				signed, _ := tpi["signed"].(map[string]any)
				if token, ok := signed["token"].(string); ok {
					add(stateTuple{"m.room.third_party_invite", token})
				}
			}
		}
		if m == "join" {
			if u, ok := c["join_authorised_via_users_server"].(string); ok {
				add(stateTuple{"m.room.member", u})
			}
		}
	}
	return out
}

// loadAuthState reads ev's auth events from the room's current state.
func loadAuthState(q querier, ev *Event) (authState, []string, error) {
	auth := authState{}
	var ids []string
	for _, t := range authTypes(ev) {
		e, err := getStateEvent(q, ev.RoomID, t.typ, t.key)
		if err != nil {
			return nil, nil, err
		}
		if e != nil {
			auth[t] = e
			ids = append(ids, e.EventID)
		}
	}
	return auth, ids, nil
}

// ---- the auth rules ----

func authErr(msg string) error { return errForbidden(msg) }

// checkCreate is auth rule 1. Like Synapse, "creator" is required by the
// room's version, not the one in the content.
func checkCreate(r roomRules, ev *Event, prevEvents []string) error {
	if len(prevEvents) > 0 {
		return authErr("create event has previous events")
	}
	if domainOf(ev.RoomID) != domainOf(ev.Sender) {
		return authErr("create event's room ID and sender are on different servers")
	}
	c := contentOf(ev)
	ver := "1"
	if v, ok := c["room_version"]; ok {
		s, isStr := v.(string)
		if !isStr {
			return authErr("unsupported room version")
		}
		ver = s
	}
	if !knownRoomVersions[ver] {
		return authErr("unsupported room version " + ver)
	}
	if !r.implicitCreator {
		if _, ok := c["creator"]; !ok {
			return authErr("create event has no creator")
		}
	}
	return nil
}

// checkAuth runs the state-dependent rules (4+) against auth. prevEvents is
// only needed for the creator's first join.
func checkAuth(version string, ev *Event, prevEvents []string, auth authState) error {
	r, ok := rulesFor(version)
	if !ok {
		return authErr("unsupported room version")
	}
	if ev.Type == "m.room.create" {
		return checkCreate(r, ev, prevEvents)
	}
	create := auth[createTuple]
	if create == nil {
		return authErr("no create event in auth events")
	}
	if domainOf(create.Sender) != domainOf(ev.Sender) && !canFederate(auth) {
		return authErr("this room has been marked as unfederatable")
	}
	if ev.Type == "m.room.member" {
		return checkMembership(r, ev, prevEvents, auth)
	}
	if m := auth[stateTuple{"m.room.member", ev.Sender}]; m == nil || membershipOf(m) != "join" {
		return authErr("you are not joined to this room")
	}
	userLevel := userPowerLevel(r, ev.Sender, auth)
	if ev.Type == "m.room.third_party_invite" {
		if userLevel < namedLevel(auth, "invite", 0) {
			return authErr("you don't have permission to invite users")
		}
		return nil
	}
	if need := sendLevel(ev.Type, ev.StateKey != nil, auth); userLevel < need {
		return authErr("you need power level " + strconv.FormatInt(need, 10) + " to send " + ev.Type)
	}
	if ev.StateKey != nil && strings.HasPrefix(*ev.StateKey, "@") && *ev.StateKey != ev.Sender {
		return authErr("you are not allowed to set others' state")
	}
	if ev.Type == "m.room.power_levels" {
		return checkPowerLevels(r, ev, auth)
	}
	// redactions pass here in v3+; redact() decides if they apply
	return nil
}

func checkMembership(r roomRules, ev *Event, prevEvents []string, auth authState) error {
	if ev.StateKey == nil {
		return authErr("membership event without a state key")
	}
	c := contentOf(ev)
	membership, ok := c["membership"].(string)
	if !ok {
		return authErr("membership event without a membership")
	}
	target := *ev.StateKey
	create := auth[createTuple]

	// The creator's own first join, straight after the create event.
	if len(prevEvents) == 1 && membership == "join" && create != nil && prevEvents[0] == create.EventID &&
		creatorOf(r, create) == target {
		return nil
	}
	if create == nil {
		return authErr("no create event in auth events")
	}
	if domainOf(create.Sender) != domainOf(target) && !canFederate(auth) {
		return authErr("this room has been marked as unfederatable")
	}

	caller := membershipOf(auth[stateTuple{"m.room.member", ev.Sender}])
	callerIn, callerInvited, callerKnocked := caller == "join", caller == "invite", caller == "knock"
	targetM := membershipOf(auth[stateTuple{"m.room.member", target}])
	targetIn, targetBanned := targetM == "join", targetM == "ban"

	joinRule := "invite"
	if jr := auth[jrTuple]; jr != nil {
		if v, ok := contentOf(jr)["join_rule"]; ok {
			joinRule = "\x00" // present but not a string (even null): matches no rule
			if s, isStr := v.(string); isStr {
				joinRule = s
			}
		}
	}
	userLevel := userPowerLevel(r, ev.Sender, auth)
	targetLevel := userPowerLevel(r, target, auth)
	inviteLevel := namedLevel(auth, "invite", 0)
	banLevel := namedLevel(auth, "ban", 50)

	if _, has := c["third_party_invite"]; has && membership == "invite" {
		if !verifyThirdPartyInvite(ev, c, auth) {
			return authErr("you are not invited to this room")
		}
		if targetBanned {
			return authErr(target + " is banned from the room")
		}
		return nil
	}

	if membership != "join" && membership != "knock" {
		if (callerInvited || callerKnocked) && membership == "leave" && target == ev.Sender {
			return nil
		}
		if !callerIn {
			return authErr("you are not joined to this room")
		}
	}

	switch membership {
	case "invite":
		if targetBanned {
			return authErr(target + " is banned from the room")
		}
		if targetIn {
			return authErr(target + " is already in the room")
		}
		if userLevel < inviteLevel {
			return authErr("you don't have permission to invite users")
		}
	case "join":
		if ev.Sender != target {
			return authErr("you can only join as yourself")
		}
		if targetBanned {
			return authErr("you are banned from this room")
		}
		switch joinRule {
		case "public":
		case "restricted", "knock_restricted":
			if callerIn || callerInvited {
				return nil
			}
			au, present := c["join_authorised_via_users_server"]
			if !present || au == nil {
				return authErr("join event is missing the authorising user")
			}
			aus, _ := au.(string)
			if !isStringValue(au) || membershipOf(auth[stateTuple{"m.room.member", aus}]) != "join" {
				return authErr("the authorising user is not in the room")
			}
			if userPowerLevel(r, aus, auth) < inviteLevel {
				return authErr("join event authorised by a user who can't invite")
			}
		case "invite", "knock":
			if !callerIn && !callerInvited {
				return authErr("you are not invited to this room")
			}
		default:
			return authErr("you are not allowed to join this room")
		}
	case "leave":
		if targetBanned && userLevel < banLevel {
			return authErr("you cannot unban " + target)
		}
		if target != ev.Sender {
			if userLevel < namedLevel(auth, "kick", 50) || userLevel <= targetLevel {
				return authErr("you cannot kick " + target)
			}
		}
	case "ban":
		if userLevel < banLevel {
			return authErr("you don't have permission to ban")
		}
		if userLevel <= targetLevel {
			return authErr("you don't have permission to ban this user")
		}
	case "knock":
		if joinRule != "knock" && joinRule != "knock_restricted" {
			return authErr("you don't have permission to knock")
		}
		if target != ev.Sender {
			return authErr("you cannot knock for other users")
		}
		if targetIn {
			return authErr("you cannot knock on a room you are already in")
		}
		if callerInvited {
			return authErr("you are already invited to this room")
		}
		if targetBanned {
			return authErr("you are banned from this room")
		}
	default:
		return authErr("unknown membership " + membership)
	}
	return nil
}

func isStringValue(v any) bool { _, ok := v.(string); return ok }

// verifyThirdPartyInvite: the signed block must match a key from the
// inviter's m.room.third_party_invite.
func verifyThirdPartyInvite(ev *Event, c map[string]any, auth authState) bool {
	tpi, ok := c["third_party_invite"].(map[string]any)
	if !ok {
		return false
	}
	signed, ok := tpi["signed"].(map[string]any)
	if !ok {
		return false
	}
	for _, k := range []string{"mxid", "token", "signatures"} {
		if _, ok := signed[k]; !ok {
			return false
		}
	}
	token, ok := signed["token"].(string)
	if !ok {
		return false
	}
	invite := auth[stateTuple{"m.room.third_party_invite", token}]
	if invite == nil || invite.Sender != ev.Sender {
		return false
	}
	if mxid, _ := signed["mxid"].(string); !isStringValue(signed["mxid"]) || mxid != *ev.StateKey {
		return false
	}
	sigs, ok := signed["signatures"].(map[string]any)
	if !ok {
		return false
	}
	servers := make([]string, 0, len(sigs))
	for s := range sigs {
		servers = append(servers, s)
	}
	sort.Strings(servers)
	ic := contentOf(invite)
	var keys []any
	if pk, ok := ic["public_key"]; ok {
		keys = append(keys, map[string]any{"public_key": pk})
	}
	if more, ok := ic["public_keys"].([]any); ok {
		keys = append(keys, more...)
	}
	for _, ko := range keys {
		// Synapse fails the whole check on a malformed key entry; so do we.
		obj, _ := ko.(map[string]any)
		pkStr, ok := obj["public_key"].(string)
		if !ok {
			return false
		}
		pub, err := decodeB64(pkStr)
		if err != nil || len(pub) != 32 {
			return false
		}
	tryKey:
		for _, server := range servers {
			block, ok := sigs[server].(map[string]any)
			if !ok {
				return false
			}
			names := make([]string, 0, len(block))
			for n := range block {
				names = append(names, n)
			}
			sort.Strings(names)
			for _, name := range names {
				if !strings.HasPrefix(name, "ed25519:") {
					continue
				}
				if verifyJSON(signed, server, name, pub) != nil {
					break tryKey // this key failed; try the next public key
				}
				return true
			}
		}
	}
	return false
}

var plTopLevels = []string{"users_default", "events_default", "state_default", "ban", "redact", "kick", "invite"}

func checkPowerLevels(r roomRules, ev *Event, auth authState) error {
	nw := contentOf(ev)
	if nw == nil {
		return errBadJSON("power levels must be an object")
	}
	newUsers, _ := nw["users"].(map[string]any)
	for k, v := range newUsers {
		if !isUserID(k) {
			return errBadJSON("not a valid user ID: " + k)
		}
		if !isInt(v) {
			return errBadJSON("not a valid power level")
		}
	}
	for _, k := range plTopLevels {
		if v, ok := nw[k]; ok && !isInt(v) {
			return errBadJSON(k + " must be an integer")
		}
	}
	for _, k := range []string{"events", "notifications", "users"} {
		v, ok := nw[k]
		if !ok {
			continue
		}
		m, isMap := v.(map[string]any)
		if !isMap {
			return errBadJSON(k + " must be an object of integers")
		}
		for _, vv := range m {
			if !isInt(vv) {
				return errBadJSON(k + " must be an object of integers")
			}
		}
	}
	cur := auth[plTuple]
	if cur == nil {
		return nil
	}
	old := contentOf(cur)
	userLevel := userPowerLevel(r, ev.Sender, auth)
	level := func(m map[string]any, k string) (int64, bool) {
		v, ok := m[k]
		if !ok {
			return 0, false
		}
		return asLevel(v), true
	}
	check := func(dir, k string, o, n map[string]any) error {
		ov, oOK := level(o, k)
		nv, nOK := level(n, k)
		if oOK && nOK && ov == nv {
			return nil
		}
		if dir == "users" && k != ev.Sender && oOK && ov == userLevel {
			return authErr("you can't change the level of a user with the same power as you")
		}
		if (oOK && ov > userLevel) || (nOK && nv > userLevel) {
			return authErr("you can't set power levels above your own")
		}
		return nil
	}
	for _, k := range plTopLevels {
		if err := check("", k, old, nw); err != nil {
			return err
		}
	}
	for _, dir := range []string{"users", "events", "notifications"} {
		o, _ := old[dir].(map[string]any)
		n, _ := nw[dir].(map[string]any)
		keys := map[string]bool{}
		for k := range o {
			keys[k] = true
		}
		for k := range n {
			keys[k] = true
		}
		for k := range keys {
			if err := check(dir, k, o, n); err != nil {
				return err
			}
		}
	}
	return nil
}

// ---- redaction ----

// redactPDU is the redaction algorithm.
func redactPDU(r roomRules, pdu map[string]any) map[string]any {
	keep := []string{"event_id", "type", "room_id", "sender", "state_key", "content", "hashes",
		"signatures", "depth", "prev_events", "auth_events", "origin_server_ts"}
	if !r.newRedaction {
		keep = append(keep, "origin", "membership", "prev_state")
	}
	out := map[string]any{}
	for _, k := range keep {
		if v, ok := pdu[k]; ok {
			out[k] = v
		}
	}
	typ, _ := pdu["type"].(string)
	content, _ := pdu["content"].(map[string]any)
	out["content"] = redactContent(r, typ, content)
	if u, ok := pdu["unsigned"].(map[string]any); ok {
		kept := map[string]any{}
		for _, k := range []string{"age_ts", "replaces_state", "redacted_because"} {
			if v, ok := u[k]; ok {
				kept[k] = v
			}
		}
		if len(kept) > 0 {
			out["unsigned"] = kept
		}
	}
	return out
}

func redactContent(r roomRules, typ string, c map[string]any) map[string]any {
	var keep []string
	switch typ {
	case "m.room.member":
		keep = []string{"membership", "join_authorised_via_users_server"}
	case "m.room.create":
		if r.newRedaction {
			out := make(map[string]any, len(c))
			for k, v := range c {
				out[k] = v
			}
			return out
		}
		keep = []string{"creator"}
	case "m.room.join_rules":
		keep = []string{"join_rule", "allow"}
	case "m.room.power_levels":
		keep = []string{"ban", "events", "events_default", "kick", "redact", "state_default", "users", "users_default"}
		if r.newRedaction {
			keep = append(keep, "invite")
		}
	case "m.room.history_visibility":
		keep = []string{"history_visibility"}
	case "m.room.redaction":
		if r.newRedaction {
			keep = []string{"redacts"}
		}
	}
	out := map[string]any{}
	for _, k := range keep {
		if v, ok := c[k]; ok {
			out[k] = v
		}
	}
	if typ == "m.room.member" && r.newRedaction {
		// An object keeps only "signed" (so {} if it has none); anything else goes.
		if tpi, ok := c["third_party_invite"].(map[string]any); ok {
			kept := map[string]any{}
			if s, ok := tpi["signed"]; ok {
				kept["signed"] = s
			}
			out["third_party_invite"] = kept
		}
	}
	return out
}

// pruneContent redacts stored client-facing content.
func pruneContent(typ string, content json.RawMessage, version string) json.RawMessage {
	r, _ := rulesFor(version)
	v, _ := decodeJSONNumbers(content)
	c, _ := v.(map[string]any)
	b, err := json.Marshal(redactContent(r, typ, c))
	if err != nil {
		return json.RawMessage("{}")
	}
	return b
}

// ---- hashes, signatures, event IDs ----

func without(m map[string]any, keys ...string) map[string]any {
	out := make(map[string]any, len(m))
	for k, v := range m {
		out[k] = v
	}
	for _, k := range keys {
		delete(out, k)
	}
	return out
}

// contentHash: sha256 of the event without unsigned, signatures, hashes.
func contentHash(pdu map[string]any) ([]byte, error) {
	b, err := canonicalJSON(without(pdu, "unsigned", "signatures", "hashes", "age_ts", "outlier", "destinations"))
	if err != nil {
		return nil, err
	}
	h := sha256.Sum256(b)
	return h[:], nil
}

// eventIDFor: sha256 of the redacted event, url-safe base64 (v4+).
func eventIDFor(r roomRules, pdu map[string]any) (string, error) {
	b, err := canonicalJSON(without(redactPDU(r, pdu), "signatures", "unsigned", "age_ts"))
	if err != nil {
		return "", err
	}
	h := sha256.Sum256(b)
	return "$" + base64.RawURLEncoding.EncodeToString(h[:]), nil
}

// hashAndSign adds hashes and our signature to a PDU and returns its event ID.
func hashAndSign(r roomRules, pdu map[string]any, server string, key signingKey) (string, error) {
	h, err := contentHash(pdu)
	if err != nil {
		return "", err
	}
	pdu["hashes"] = map[string]any{"sha256": b64.EncodeToString(h)}
	red := without(redactPDU(r, pdu), "unsigned", "age_ts")
	delete(red, "signatures")
	if err := signJSON(red, server, key); err != nil {
		return "", err
	}
	pdu["signatures"] = red["signatures"]
	return eventIDFor(r, pdu)
}

// checkPDUHashes: false means we must treat the event as redacted.
func checkPDUHashes(pdu map[string]any) bool {
	hashes, _ := pdu["hashes"].(map[string]any)
	want, _ := hashes["sha256"].(string)
	got, err := contentHash(pdu)
	if err != nil {
		return false
	}
	wb, err := decodeB64(want)
	return err == nil && string(wb) == string(got)
}

// verifyPDUSignature checks the sender server's signature on a PDU.
func verifyPDUSignature(r roomRules, pdu map[string]any, server, keyID string, pub []byte) error {
	red := without(redactPDU(r, pdu), "unsigned", "age_ts")
	return verifyJSON(red, server, keyID, pub)
}

// ---- storing local events in federated rooms ----

const maxDepth = math.MaxInt64

// roomInfo is what storing an event needs to know about its room.
type roomInfo struct {
	version   string
	federated bool
}

func getRoomInfo(q querier, roomID string) (roomInfo, bool) {
	var ri roomInfo
	var fed int
	if q.QueryRow("SELECT version, federated FROM rooms WHERE room_id = ?", roomID).Scan(&ri.version, &fed) != nil {
		return ri, false
	}
	ri.federated = fed == 1
	return ri, true
}

// prevEventsFor returns prev_events and depth for a new event. Local rooms
// are a straight line, so that's just the last event.
func prevEventsFor(q querier, roomID string, federated bool) ([]string, int64, error) {
	if !federated {
		var id string
		err := q.QueryRow("SELECT event_id FROM events WHERE room_id = ? ORDER BY stream DESC LIMIT 1", roomID).Scan(&id)
		if errors.Is(err, sql.ErrNoRows) {
			return nil, 1, nil
		}
		return []string{id}, 0, err
	}
	rows, err := q.Query("SELECT event_id, depth FROM room_extremities WHERE room_id = ? ORDER BY depth DESC, event_id LIMIT 10", roomID)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	var ids []string
	var depth int64
	for rows.Next() {
		var id string
		var d int64
		if err := rows.Scan(&id, &d); err != nil {
			return nil, 0, err
		}
		ids = append(ids, id)
		depth = max(depth, d)
	}
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}
	if depth < maxDepth {
		depth++
	}
	return ids, depth, nil
}

// buildPDU signs a local event and sets its ID. Content becomes canonical
// (1.0 -> 1); floats can't be signed and are refused.
func (s *Server) buildPDU(tx *sql.Tx, r roomRules, ev *Event, prevEvents, authEvents []string, depth int64) ([]byte, error) {
	if s.fedKey.priv == nil {
		k, err := loadSigningKey(tx)
		if err != nil {
			return nil, err
		}
		s.fedKey = k
	}
	content, err := decodeJSONNumbers(ev.Content)
	if err != nil {
		return nil, errBadJSON("invalid content")
	}
	canon, err := canonicalJSON(content)
	if err != nil {
		return nil, errBadJSON("content can't be signed: " + err.Error() + " (federated rooms only allow integers)")
	}
	if prevEvents == nil {
		prevEvents = []string{}
	}
	if authEvents == nil {
		authEvents = []string{}
	}
	pdu := map[string]any{
		"auth_events": authEvents, "prev_events": prevEvents, "type": ev.Type, "sender": ev.Sender,
		"content": content, "depth": depth, "room_id": ev.RoomID, "origin_server_ts": ev.OriginTS,
	}
	if ev.StateKey != nil {
		pdu["state_key"] = *ev.StateKey
	}
	if ev.Type == "m.room.redaction" && !r.newRedaction {
		if red, ok := content.(map[string]any)["redacts"].(string); ok {
			pdu["redacts"] = red
		}
	}
	id, err := hashAndSign(r, pdu, s.cfg.ServerName, s.fedKey)
	if err != nil {
		return nil, err
	}
	out, err := canonicalJSON(pdu)
	if err != nil {
		return nil, err
	}
	if len(out) > maxPDUSize {
		return nil, errf(413, "M_TOO_LARGE", "event too large")
	}
	ev.EventID = id
	ev.Content = canon
	return out, nil
}

// redactStoredPDU applies a redaction to a stored PDU.
func redactStoredPDU(version, pduJSON string) (string, error) {
	r, _ := rulesFor(version)
	v, err := decodeJSONNumbers([]byte(pduJSON))
	if err != nil {
		return "", err
	}
	m, ok := v.(map[string]any)
	if !ok {
		return "", errors.New("stored PDU is not an object")
	}
	b, err := canonicalJSON(redactPDU(r, m))
	return string(b), err
}
